-- scripts/20261122_fix_categorias_contables_identity.sql
-- Corrección de columna identidad en categorias_contables
-- Convierte GENERATED ALWAYS a GENERATED BY DEFAULT para admitir tanto
-- auto-generación por secuencia como IDs explícitos, y sincroniza la secuencia oficial.

BEGIN;

ALTER TABLE public.categorias_contables 
    ALTER COLUMN id SET GENERATED BY DEFAULT;

SELECT setval(
    'public.categorias_contables_id_seq', 
    (SELECT COALESCE(MAX(id), 1) FROM public.categorias_contables)
);

COMMIT;
